    if (!startTime) startTime = timestamp;
    const delta = timestamp - (lastRender || timestamp);
    lastRender = timestamp;

    // clear and draw background
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    drawStars();
    update(delta);
    drawShip();
